/// Room statistic name.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum UserRoomStatName {
    /// `creepsLost`.
    #[serde(rename = "creepsLost")]
    CreepsLost,
    /// `creepsProduced`.
    #[serde(rename = "creepsProduced")]
    CreepsProduced,
    /// `energyConstruction`.
    #[serde(rename = "energyConstruction")]
    EnergyConstruction,
    /// `energyControl`.
    #[serde(rename = "energyControl")]
    EnergyControl,
    /// `energyCreeps`.
    #[serde(rename = "energyCreeps")]
    EnergyCreeps,
    /// `energyHarvested`.
    #[serde(rename = "energyHarvested")]
    EnergyHarvested,
    /// `powerProcessed`.
    #[serde(rename = "powerProcessed")]
    PowerProcessed,
}

impl UserRoomStatName {
    /// The JSON string of the variant.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::CreepsLost => "creepsLost",
            Self::CreepsProduced => "creepsProduced",
            Self::EnergyConstruction => "energyConstruction",
            Self::EnergyControl => "energyControl",
            Self::EnergyCreeps => "energyCreeps",
            Self::EnergyHarvested => "energyHarvested",
            Self::PowerProcessed => "powerProcessed",
        }
    }
}

/// Sum of each room statistic over the window, keyed by statistic name. Known names: `creepsLost`, `creepsProduced`, `energyConstruction`, `energyControl`, `energyCreeps`, `energyHarvested`, `powerProcessed`.
pub type UserRoomStatValues = BTreeMap<String, f64>;

