/// `empty`: no objects in the world (new or respawned, must place a spawn); `normal`: owns a spawn in a room whose controller it owns; `lost`: has objects but no such spawn (may respawn).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum UserWorldStatus {
    /// `empty`.
    #[serde(rename = "empty")]
    Empty,
    /// `normal`.
    #[serde(rename = "normal")]
    Normal,
    /// `lost`.
    #[serde(rename = "lost")]
    Lost,
}

impl UserWorldStatus {
    /// The JSON string of the variant.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Empty => "empty",
            Self::Normal => "normal",
            Self::Lost => "lost",
        }
    }
}

